        You are a programming expert. 
        You will be provided with a patch used to fix a bug. 
        Based on the commit message and modifications in the patch, you need to analyze the root cause of the bug in detail. 

        Here is the patch content:
        From 813108a928fd50a1fb87e9333b974b6e7242b117 Mon Sep 17 00:00:00 2001
From: Sam Brannen <sam@sambrannen.com>
Date: Sun, 10 Jul 2016 16:00:30 +0200
Subject: [PATCH] Ensure TestContextManager always tracks after-class exception

This commit fixes a minor bug introduced in 0adc4921ed.

Issue: SPR-14447
---
 .../springframework/test/context/TestContextManager.java    | 6 +++---
 1 file changed, 3 insertions(+), 3 deletions(-)

diff --git a/spring-test/src/main/java/org/springframework/test/context/TestContextManager.java b/spring-test/src/main/java/org/springframework/test/context/TestContextManager.java
index 3359852074..289796477e 100644
--- a/spring-test/src/main/java/org/springframework/test/context/TestContextManager.java
+++ b/spring-test/src/main/java/org/springframework/test/context/TestContextManager.java
@@ -366,9 +366,9 @@ public class TestContextManager {
 				if (logger.isWarnEnabled()) {
 					logger.warn("Caught exception while allowing TestExecutionListener [" + testExecutionListener +
 							"] to process 'after class' callback for test class [" + testClass + "]", ex);
-					if (afterTestClassException == null) {
-						afterTestClassException = ex;
-					}
+				}
+				if (afterTestClassException == null) {
+					afterTestClassException = ex;
 				}
 			}
 		}
-- 
